--
-- Table structure for table `transactions`
--

DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `seller_type` enum('Individual','Farmer Organization') NOT NULL,
  `procurement_type` enum('In-Warehouse','Mobile Procurement') NOT NULL,
  `farmer_id` bigint(20) unsigned DEFAULT NULL,
  `farmer_organization_id` bigint(20) unsigned DEFAULT NULL,
  `representative_name` varchar(180) DEFAULT NULL,
  `total_members` int(10) unsigned DEFAULT NULL,
  `verified_farm_area` decimal(10,3) DEFAULT NULL,
  `delivery_date` date NOT NULL,
  `warehouse_stock_receipt_number` varchar(80) NOT NULL,
  `palay_variety` varchar(10) NOT NULL DEFAULT 'PD1',
  `price_per_kilogram` decimal(10,3) NOT NULL,
  `net_kilogram` decimal(12,3) NOT NULL,
  `bags_50kg` decimal(12,3) NOT NULL,
  `warehouse_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `is_ip_group_delivery` tinyint(1) NOT NULL DEFAULT 0,
  `total_cost` decimal(20,2) GENERATED ALWAYS AS (round(`price_per_kilogram` * `net_kilogram`,2)) STORED,
  `client_control_number` varchar(96) DEFAULT NULL,
  `total_amount` decimal(20,3) NOT NULL DEFAULT 0.000,
  PRIMARY KEY (`id`),
  UNIQUE KEY `warehouse_stock_receipt_number` (`warehouse_stock_receipt_number`),
  UNIQUE KEY `transactions_client_control_number_unique` (`client_control_number`),
  KEY `farmer_id` (`farmer_id`),
  KEY `farmer_organization_id` (`farmer_organization_id`),
  KEY `created_by` (`created_by`),
  KEY `warehouse_id` (`warehouse_id`),
  CONSTRAINT `transactions_ibfk_1` FOREIGN KEY (`farmer_id`) REFERENCES `farmers` (`id`),
  CONSTRAINT `transactions_ibfk_2` FOREIGN KEY (`farmer_organization_id`) REFERENCES `farmer_organizations` (`id`),
